import type { createClient } from "https://esm.sh/@supabase/supabase-js@2";

type Supabase = ReturnType<typeof createClient>;

export type Caller =
  | { kind: "cron" }
  | { kind: "user"; userId: string };

export async function authorizeCronOrUser(req: Request, supabase: Supabase): Promise<Caller | null> {
  const cronHeader = req.headers.get("x-cron-secret") || "";
  const auth = req.headers.get("authorization") || "";
  const bearer = auth.startsWith("Bearer ") ? auth.slice(7) : "";

  const envSecret = Deno.env.get("CRON_SECRET") || "";
  if (envSecret && (cronHeader === envSecret || bearer === envSecret)) {
    return { kind: "cron" };
  }

  const { data: cfg } = await supabase.from("automation_config").select("cron_secret").eq("id", 1).maybeSingle();
  const stored = (cfg as { cron_secret?: string } | null)?.cron_secret || "";
  if (stored && (cronHeader === stored || bearer === stored)) {
    return { kind: "cron" };
  }

  if (bearer && bearer !== envSecret && bearer !== stored) {
    const { data, error } = await supabase.auth.getUser(bearer);
    if (!error && data.user?.id) return { kind: "user", userId: data.user.id };
  }
  return null;
}

export async function requireUser(req: Request, supabase: Supabase): Promise<string | null> {
  const auth = req.headers.get("authorization") || "";
  if (!auth.startsWith("Bearer ")) return null;
  const { data, error } = await supabase.auth.getUser(auth.slice(7));
  if (error || !data.user?.id) return null;
  return data.user.id;
}

type LogFields = Record<string, unknown>;

function sanitize(fields: LogFields): LogFields {
  const out: LogFields = {};
  for (const [k, v] of Object.entries(fields)) {
    const key = k.toLowerCase();
    if (key.includes("token") || key.includes("secret") || key.includes("authorization") || key.includes("password") || key.includes("apikey") || key.includes("api_key")) {
      continue;
    }
    out[k] = v;
  }
  return out;
}

export function jobLog(event: string, fields: LogFields = {}) {
  console.log(JSON.stringify({ event, ts: new Date().toISOString(), ...sanitize(fields) }));
}

const WEEKDAY: Record<string, number> = {
  Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7,
};

export function wallTimeToUtc(localIsoDate: string, hour: number, minute: number, timeZone: string): Date {
  const hh = String(hour).padStart(2, "0");
  const mi = String(minute).padStart(2, "0");
  const local = `${localIsoDate}T${hh}:${mi}:00`;
  const asUtc = new Date(`${local}Z`).getTime();
  const tzString = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).format(new Date(asUtc));
  const m = tzString.match(/(\d{2})\/(\d{2})\/(\d{4}),?\s+(\d{2}):(\d{2})/);
  let offsetMin = 0;
  if (m) {
    const tzAsUtc = Date.UTC(+m[3], +m[1] - 1, +m[2], +m[4], +m[5]);
    offsetMin = (asUtc - tzAsUtc) / 60000;
  }
  return new Date(asUtc + offsetMin * 60000);
}

export function computeNextRun(
  daysOfWeek: number[],
  hour: number,
  minute: number,
  timeZone: string,
  from: Date = new Date(),
): Date {
  if (!daysOfWeek?.length) return new Date(from.getTime() + 24 * 3600_000);
  const days = new Set(daysOfWeek);
  for (let i = 0; i < 14; i++) {
    const candidate = new Date(from.getTime() + i * 24 * 3600_000);
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone,
      weekday: "short",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).formatToParts(candidate).reduce<Record<string, string>>((acc, p) => {
      acc[p.type] = p.value;
      return acc;
    }, {});
    const wd = WEEKDAY[parts.weekday];
    if (!days.has(wd)) continue;
    const target = wallTimeToUtc(`${parts.year}-${parts.month}-${parts.day}`, hour, minute, timeZone);
    if (target.getTime() > from.getTime()) return target;
  }
  return new Date(from.getTime() + 24 * 3600_000);
}

export function makeIdempotencyKey(parts: {
  postId?: string | null;
